import{_ as t,o as a,c as s,a5 as o}from"./chunks/framework.DukzBDYY.js";const p=JSON.parse('{"title":"Privacy and Data","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/privacy.md","filePath":"getting-started/privacy.md"}'),r={name:"getting-started/privacy.md"};function n(i,e,d,h,l,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy-and-data" tabindex="-1">Privacy and Data <a class="header-anchor" href="#privacy-and-data" aria-label="Permalink to &quot;Privacy and Data&quot;">​</a></h1><p>Delivery Slots stores little of its own. Customer details stay in Commerce orders and addresses; the plugin adds when each order is delivered.</p><h2 id="what-it-stores" tabindex="-1">What it stores <a class="header-anchor" href="#what-it-stores" aria-label="Permalink to &quot;What it stores&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Holds</th></tr></thead><tbody><tr><td><code>deliveryslots_schedules</code></td><td>Each shipping method’s windows, limits, closed days, date changes and zones</td></tr><tr><td><code>deliveryslots_bookings</code></td><td>For each order with a slot: the shipping method, date, times, zone, fee, and whether it’s held or booked</td></tr></tbody></table><p>Bookings hold no names, emails, phone numbers or addresses. When an order is deleted, its booking is deleted with it.</p><h2 id="who-can-see-customer-details" tabindex="-1">Who can see customer details <a class="header-anchor" href="#who-can-see-customer-details" aria-label="Permalink to &quot;Who can see customer details&quot;">​</a></h2><ul><li><strong>The run sheet, packing list, exports and print views</strong> show names, phone numbers, emails and addresses from orders. Only users with the <strong>View the run sheet</strong> permission can open them, and only in the control panel.</li><li><strong>Exported CSV files</strong> contain personal data. Store and share them as you would any customer list, and delete them when you’re done.</li><li><strong>Changing an order’s slot</strong> needs Commerce’s <strong>Edit orders</strong> permission.</li></ul><h2 id="what-customers-can-see" tabindex="-1">What customers can see <a class="header-anchor" href="#what-customers-can-see" aria-label="Permalink to &quot;What customers can see&quot;">​</a></h2><ul><li><strong>The slot picker and JSON actions</strong> show only the visitor’s own cart and how many places are left in each slot. They never show other customers’ orders.</li><li><strong>The calendar link</strong> (<code>slot.calendarUrl</code>) uses the order’s 32-character number, which only the customer has. It works only for completed orders, and includes the shipping address as the event’s location.</li></ul><h2 id="emails" tabindex="-1">Emails <a class="header-anchor" href="#emails" aria-label="Permalink to &quot;Emails&quot;">​</a></h2><p>When staff change an order’s slot with <strong>Email the customer</strong> ticked, the customer gets an email at the order’s address, sent with Craft’s own email settings. Nothing else is emailed by the plugin.</p><h2 id="sent-to-other-services" tabindex="-1">Sent to other services <a class="header-anchor" href="#sent-to-other-services" aria-label="Permalink to &quot;Sent to other services&quot;">​</a></h2><p>Delivery Slots doesn’t send data anywhere itself.</p><p>With <a href="/guides/zones">zones</a>, the shipping address is placed on the map by Geo Maps. Addresses with coordinates are used as they are. Others are looked up with Geo Maps’ map service (OpenStreetMap, Mapbox or Google), which receives the street, suburb, postcode and country, but no name or contact details. See Geo Maps’ privacy notes for each service.</p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p>Craft’s logs record a slot that couldn’t be held for a new cart, with the slot’s value and the reason. They don’t include customer details.</p>',16)])])}const u=t(r,[["render",n]]);export{p as __pageData,u as default};
